import torch
data = torch.load('dataset.pt', map_location='cpu')
if isinstance(data, dict):
    for k, v in data.items():
        if hasattr(v, 'shape'):
            print(f'{k}: {v.shape} {v.dtype}')
        else:
            print(f'{k}: {type(v)}')
elif isinstance(data, (list, tuple)):
    for i, v in enumerate(data):
        if hasattr(v, 'shape'):
            print(f'[{i}]: {v.shape} {v.dtype}')
        else:
            print(f'[{i}]: {type(v)}')
